/**
 * Copies the art the app uses from `art/source` (the asset pack, regenerated by `gen.py`) into
 * `app/src/assets/game`, where Vite fingerprints it and the service worker caches it with the app shell.
 * Run after changing the pack: `pnpm --filter @ld/app-pixel-pitch art:build`. The output is committed, so CI and
 * fresh clones need neither Python nor this step.
 */
import { cpSync, existsSync, mkdirSync, rmSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'

const here = path.dirname(new URL(import.meta.url).pathname)
const source = path.join(here, 'source')
const target = path.resolve(here, '../app/src/assets/game')

// Only what the screens draw. Audio waits for the sound milestone (it needs converting to m4a/ogg first).
const FOLDERS = [
  'sprites/players',
  'sprites/crests',
  'sprites/flags',
  'sprites/pitch',
  'sprites/icons',
  'sprites/badges',
  'sprites/cards',
  'sprites/text',
  'sprites/ui',
  'sprites/club',
]

if (!existsSync(source)) {
  console.error(`No asset pack at ${source}.`)
  process.exit(1)
}

rmSync(target, { recursive: true, force: true })
for (const folder of FOLDERS) {
  const destination = path.join(target, folder.replace(/^sprites\//, ''))
  mkdirSync(path.dirname(destination), { recursive: true })
  cpSync(path.join(source, folder), destination, { recursive: true, filter: file => !file.endsWith('.DS_Store') })
}
cpSync(path.join(source, 'palette/palette.json'), path.join(target, 'palette.json'))
console.log(`Copied ${FOLDERS.length} folders of art into ${path.relative(process.cwd(), target)}.`)
